package net.officefloor.hq.app;

/**
 * A project as the list shows it: its own id and name plus the belonging client's NAME (not id), so
 * the front-end renders the cross-entity join without a second request. Built by the JPQL
 * constructor expression in {@link ProjectRepository#findAllViews()}.
 */
public class ProjectView {

    private final Long id;
    private final String name;
    private final String clientName;

    public ProjectView(Long id, String name, String clientName) {
        this.id = id;
        this.name = name;
        this.clientName = clientName;
    }

    public Long getId() {
        return id;
    }

    public String getName() {
        return name;
    }

    public String getClientName() {
        return clientName;
    }
}
===V4===
-- Invoices: the third domain table. An invoice has a monetary amount and belongs to a project
-- (project_id FK). GENERATED BY DEFAULT (not ALWAYS) so the /__test__ seed path can insert
-- explicit fixture ids.
CREATE TABLE invoices (
    id         BIGINT        GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    project_id BIGINT        NOT NULL REFERENCES projects(id),
    amount     DECIMAL(12,2) NOT NULL
);
===V5===
-- Invoices gain a payment status so an invoice can be marked paid. Additive column with a NOT NULL
-- default of 'UNPAID' so every existing row (and any insert that omits it) starts unpaid; the app
-- flips it to 'PAID' when the invoice is paid.
ALTER TABLE invoices ADD COLUMN status VARCHAR(16) NOT NULL DEFAULT 'UNPAID';

